 function landingFace(s,c){
  if(!s||!c)return;
  const index=s.landing?.indexOf(FOF.nameAt(c))??-1;
  if(index<0)return;
  const count=FOF.scenario(s.id)?.terrainSetup?.landingCount;
  if(count===3&&index<3)return 'lz-large-'+(index+1);
  if(count===1)return 'vn-lz';
 }
